#!/usr/bin/env python3
# Author physics-verified Nav + Radio-Nav questions. Every correct answer is
# COMPUTED here from the governing formula, so it is provably right; distractors
# are near-miss values (not obvious). Maps only to real SACAA aspects.
import math, sys

HDR = '''// {kind} — questions authored from textbook physics (CAE Oxford / SACAA syllabus).
// Each correct answer is COMPUTED from the governing formula (shown in the
// explanation), so it is provably correct; distractors are near-miss values.
// Generated by scripts/gen.py — do not hand-edit; regenerate instead.

import type {{ AirLawQuestion }} from "@/app/data/airlaw-questions";

const Q = (id: string, sectionId: string, question: string, a: string, b: string, c: string, d: string, correct: "a" | "b" | "c" | "d", explanation: string, difficulty: "easy" | "medium" | "hard" = "medium"): AirLawQuestion =>
  ({{ id, sectionId, question, optionA: a, optionB: b, optionC: c, optionD: d, correctAnswer: correct, explanation, difficulty }});

export const {var}: AirLawQuestion[] = [
'''

def esc(s): return s.replace('\\','\\\\').replace('"','\\"')

class Bank:
    def __init__(self, prefix):
        self.prefix=prefix; self.n=0; self.rows=[]; self.seen=set()
    def add(self, sec, q, opts, cidx, expl, diff="medium"):
        key=(q,)  # dedupe identical stems
        if key in self.seen: return
        self.seen.add(key)
        self.n+=1
        a,b,c,d=opts
        letter="abcd"[cidx]
        self.rows.append(f'  Q("{self.prefix}-{self.n:04d}", "{sec}", "{esc(q)}", "{esc(a)}", "{esc(b)}", "{esc(c)}", "{esc(d)}", "{letter}", "{esc(expl)}", "{diff}"),')
    # numeric helper: correct value + 3 distractor values -> 4 formatted options, rotated
    def num(self, sec, q, correct, distractors, fmt, expl, diff="medium"):
        vals=[correct]+list(distractors)
        # ensure distinct after formatting
        out=[]; used=set()
        for v in vals:
            s=fmt(v);
            # nudge collisions
            bump=0
            while s in used:
                bump+=1; v=v+max(abs(v)*0.02,0.3)*bump; s=fmt(v)
                if bump>50: s=s+f" ({bump})"; break
            used.add(s); out.append(s)
        pos=(self.n)%4
        opts=out[1:]
        opts.insert(pos, out[0])
        self.add(sec, q, opts, pos, expl, diff)
    def text(self, sec, q, correct, wrong3, expl, diff="medium"):
        pos=(self.n)%4
        opts=list(wrong3); opts.insert(pos, correct)
        self.add(sec, q, opts, pos, expl, diff)
    def dump(self, kind, var, path):
        body=HDR.format(kind=kind, var=var)+"\n".join(self.rows)+"\n];\n"
        open(path,"w").write(body)

# ───────────────────────── NAVIGATION ─────────────────────────
N=Bank("NAUT")
i0=lambda v: f"{round(v)}"
i1=lambda v: f"{v:.1f}"
i2=lambda v: f"{v:.2f}"

# A.9.7  TAS from Mach + SAT   a=38.95*sqrt(T_K); TAS=M*a
for M in [0.74,0.76,0.78,0.80,0.82,0.84,0.86,0.88]:
    for T in [-35,-45,-50,-55,-60,-65,-20]:
        TK=T+273.0; a=38.95*math.sqrt(TK); tas=M*a
        N.num("A.9.7",
            f"An aircraft flies at Mach {M:.2f} where the SAT is {T}°C. What is the TAS?",
            tas,
            [661.5*M, tas*1.06, tas*0.93],
            i0,
            f"LSS a = 38.95√T(K) = 38.95√{TK:.0f} = {a:.0f} kt; TAS = M × a = {M:.2f} × {a:.0f} ≈ {tas:.0f} kt.",
            "hard")

# A.9.7  Mach from TAS + SAT
for TAS in [440,470,500,520,540,300,360]:
    for T in [-40,-50,-56,-20,15,-10]:
        TK=T+273.0; a=38.95*math.sqrt(TK); M=TAS/a
        N.num("A.9.7",
            f"TAS is {TAS} kt and SAT is {T}°C. What is the Mach number?",
            M, [TAS/661.5, M+0.05, M-0.06], i2,
            f"a = 38.95√{TK:.0f} = {a:.0f} kt; M = TAS/a = {TAS}/{a:.0f} ≈ {M:.2f}.","medium")

# A.9.7  Local speed of sound
for T in [15,0,-15,-30,-45,-56,30,-5]:
    TK=T+273.0; a=38.95*math.sqrt(TK)
    N.num("A.9.7",
        f"What is the local speed of sound at an air temperature of {T}°C?",
        a, [38.95*math.sqrt(abs(T) if T else 1), a*1.05, a*0.94], i0,
        f"a = 38.95 × √T(K); T = {T}+273 = {TK:.0f} K; a = 38.95√{TK:.0f} ≈ {a:.0f} kt.","medium")

# A.9.8  1-in-60 track error
for off in [2,3,4,5,6,8,10]:
    for gone in [30,40,50,60,80,100,120]:
        te=60.0*off/gone
        N.num("A.9.8",
            f"After flying {gone} NM you are {off} NM right of track. What is your track error angle (1-in-60)?",
            te, [60.0*off/(gone+30), te*1.4, te*0.65], i1,
            f"Track error = 60 × (distance off ÷ distance gone) = 60 × {off}/{gone} ≈ {te:.1f}°.","medium")

# A.9.8  1-in-60 total alteration (close at destination)
for off in [3,4,5,6]:
    for gone in [40,60,80] :
        for rem in [60,100,140]:
            te=60.0*off/gone; ca=60.0*off/rem; tot=te+ca
            N.num("A.9.8",
                f"You are {off} NM right of track after {gone} NM; {rem} NM remain to destination. By how much must you alter heading left to arrive on track?",
                tot, [te, ca, tot*1.25], i1,
                f"Track error = 60×{off}/{gone} = {te:.1f}°; closing angle = 60×{off}/{rem} = {ca:.1f}°; total alteration = {te:.1f}+{ca:.1f} ≈ {tot:.1f}°.","hard")

# A.9.1  Departure = chlong(min) * cos(lat)
for lat in [10,25,30,40,45,50,55,60]:
    for cl in [60,120,180,240,300]:
        dep=cl*math.cos(math.radians(lat))
        N.num("A.9.1",
            f"Two positions on latitude {lat}° are {cl}' of longitude apart. What is the east-west distance (departure)?",
            dep, [float(cl), cl*math.sin(math.radians(lat)), dep*0.9], i0,
            f"Departure = d.long(min) × cos(lat) = {cl} × cos{lat}° = {cl} × {math.cos(math.radians(lat)):.3f} ≈ {dep:.0f} NM.","medium")

# A.9.1  ch.long from departure
for lat in [20,35,45,52,58,62]:
    for dep in [60,100,150,200]:
        cl=dep/math.cos(math.radians(lat))
        N.num("A.9.1",
            f"An aircraft on latitude {lat}° flies {dep} NM due east. Through how many minutes of longitude does it pass?",
            cl, [float(dep), dep*math.cos(math.radians(lat)), cl*1.1], i0,
            f"d.long = departure ÷ cos(lat) = {dep} ÷ cos{lat}° = {dep} ÷ {math.cos(math.radians(lat)):.3f} ≈ {cl:.0f}'.","medium")

# A.9.1  Convergency = chlong(deg) * sin(mean lat)
for ml in [15,30,40,45,55,60,70]:
    for cl in [10,20,30,40]:
        cv=cl*math.sin(math.radians(ml))
        N.num("A.9.1",
            f"The change of longitude between two positions is {cl}° at a mean latitude of {ml}°. What is the Earth convergency?",
            cv, [float(cl), cl*math.cos(math.radians(ml)), cv*1.15], i1,
            f"Convergency = d.long × sin(mean lat) = {cl}° × sin{ml}° = {cl} × {math.sin(math.radians(ml)):.3f} ≈ {cv:.1f}°.","medium")

# A.9.5  Conversion angle = 0.5 * convergency
for ml in [20,35,45,55,65]:
    for cl in [12,24,36,48]:
        ca=0.5*cl*math.sin(math.radians(ml))
        N.num("A.9.5",
            f"On a Mercator chart the rhumb-line track between two points differs from the great-circle track. If d.long is {cl}° and mean latitude {ml}°, what is the conversion angle?",
            ca, [cl*math.sin(math.radians(ml)), ca*1.3, ca*0.6], i1,
            f"Conversion angle = ½ × convergency = ½ × {cl}° × sin{ml}° ≈ {ca:.1f}°.","hard")

# A.9.5  Lambert n = sin(parallel of origin)
for p1,p2 in [(30,50),(37,65),(40,48),(33,45),(50,70),(10,30)]:
    po=(p1+p2)/2; n=math.sin(math.radians(po))
    N.num("A.9.5",
        f"A Lambert conformal conic chart has standard parallels {p1}°N and {p2}°N. What is the constant of the cone (n)?",
        n, [math.sin(math.radians(p1)), math.sin(math.radians(p2)), n*0.9], i2,
        f"n = sin(parallel of origin) = sin((({p1}+{p2})/2)°) = sin{po:.0f}° ≈ {n:.2f}.","hard")
    for cl in [10,20,30]:
        conv=cl*n
        N.num("A.9.5",
            f"On a Lambert chart with standard parallels {p1}°N/{p2}°N (n=sin origin), two meridians are {cl}° of longitude apart. What is the chart convergence between them?",
            conv, [float(cl), cl*math.sin(math.radians(p1)), conv*1.2], i1,
            f"Chart convergence = d.long × n = {cl}° × {n:.3f} ≈ {conv:.1f}°.","medium")

# A.9.5  Mercator scale: scale factor = sec(lat) relative to equator
for lat in [20,30,40,45,50,60]:
    sf=1/math.cos(math.radians(lat))
    N.num("A.9.5",
        f"On a normal Mercator chart whose scale is correct at the Equator, by what factor is the scale expanded at latitude {lat}°?",
        sf, [math.cos(math.radians(lat)), sf*1.1, math.tan(math.radians(lat))+1], i2,
        f"Mercator scale expands as the secant of latitude: sec{lat}° = 1/cos{lat}° ≈ {sf:.2f}.","medium")

# A.9.3  Distance unit conversions
pairs=[("NM","km",1.852),("km","NM",1/1.852),("NM","statute miles",1.15078),("statute miles","NM",1/1.15078),("km","statute miles",0.621371),("statute miles","km",1.609344)]
for frm,to,k in pairs:
    for v in [10,25,50,100,150,200,300]:
        res=v*k
        N.num("A.9.3",
            f"Convert {v} {frm} to {to}.",
            res, [v/k, v, res*1.05], i1,
            f"{v} {frm} × {k:.4f} = {res:.1f} {to}.","easy")

# A.9.3  Latitude change from distance N/S (60 NM = 1 deg)
for dist in [120,240,370,450,600,685]:
    dlat=dist/60.0
    N.num("A.9.3",
        f"An aircraft tracks due south for {dist} NM. Through how many degrees of latitude does it pass?",
        dlat, [dist/100.0, dist*1.852/60.0, dlat*0.9], i1,
        f"1° of latitude = 60 NM; Δlat = {dist}/60 ≈ {dlat:.1f}°.","easy")

# A.9.7  GS / ETA time-distance
for dist in [120,250,330,480,600,90,540]:
    for gs in [120,180,240,300,420,480]:
        mins=dist/gs*60.0
        N.num("A.9.7",
            f"Distance to run is {dist} NM at a groundspeed of {gs} kt. What is the time to run?",
            mins, [dist/gs*100, mins*1.1, dist/gs*50], lambda v: f"{round(v)} min",
            f"Time = distance/GS = {dist}/{gs} h = {dist/gs:.3f} h × 60 ≈ {mins:.0f} min.","easy")

# A.9.7  Wind components head/cross
for ws in [20,30,40,50]:
    for ang in [20,30,45,60,90,120,150]:
        hw=ws*math.cos(math.radians(ang)); xw=ws*math.sin(math.radians(ang))
        N.num("A.9.7",
            f"The wind is {ws} kt at {ang}° to the runway/track. What is the headwind component? (negative = tailwind)",
            hw, [xw, ws, hw*0.8], i0,
            f"Headwind = windspeed × cos(angle) = {ws} × cos{ang}° ≈ {hw:.0f} kt.","medium")
        N.num("A.9.7",
            f"The wind is {ws} kt at {ang}° to the track. What is the crosswind component?",
            xw, [hw if hw>0 else ws*0.5, ws, xw*0.85], i0,
            f"Crosswind = windspeed × sin(angle) = {ws} × sin{ang}° ≈ {xw:.0f} kt.","medium")

# A.9.7  ISA temperature at altitude
for ft in [5000,10000,18000,27000,33000,36000,40000]:
    if ft<=36089: t=15-1.98*ft/1000
    else: t=-56.5
    N.num("A.9.7",
        f"What is the ISA temperature at {ft} ft (below the tropopause lapse 1.98°C/1000 ft, isothermal above 36 090 ft)?",
        t, [15-2*ft/1000-3, t+5, t-6], i1,
        f"ISA temp = 15 − 1.98×(alt/1000) = 15 − 1.98×{ft/1000:.0f} ≈ {t:.1f}°C" + (" (capped at tropopause −56.5°C)" if ft>36089 else "")+".","medium")

# A.9.5  Chart scale: map cm -> real NM  (dist_cm * denom / 185200)
for denom in [250000,500000,1000000,1852000]:
    for cm in [4,6,10,12,20]:
        nm=cm*denom/185200.0
        N.num("A.9.5",
            f"On a chart of scale 1:{denom:,} a line measures {cm} cm. What ground distance does it represent?",
            nm, [cm*denom/100000/1.852*0.5, nm*1.15, cm*denom/185200.0/1.852], lambda v: f"{v:.0f} NM",
            f"Ground = chart dist × scale = {cm} cm × {denom:,} = {cm*denom:,} cm = {cm*denom/100000:.1f} km ÷ 1.852 ≈ {nm:.0f} NM.","hard")

# A.9.4  Arc-to-time: LMT from UTC and longitude (1 deg = 4 min)
def hhmm(mins):
    mins=int(round(mins))%1440
    return f"{mins//60:02d}{mins%60:02d}"
for lon,ew in [(15,'E'),(30,'E'),(45,'E'),(75,'E'),(120,'E'),(20,'W'),(60,'W'),(90,'W'),(135,'W')]:
    for utc in [600,1200,1800]:
        off=lon*4*(1 if ew=='E' else -1)
        lmt=utc+off
        N.text("A.9.4",
            f"UTC is {hhmm(utc)}. What is the Local Mean Time at longitude {lon}°{ew}?",
            hhmm(lmt),
            [hhmm(utc-off), hhmm(utc+off/2), hhmm(utc+lon*(1 if ew=='E' else -1))],
            f"Arc-to-time: {lon}° × 4 min = {abs(off)} min, {'added for East' if ew=='E' else 'subtracted for West'}. LMT = {hhmm(utc)} {'+' if ew=='E' else '−'} {abs(off)} min = {hhmm(lmt)}.","medium")

# A.9.6  Speed of closing / opening
for v1 in [120,180,240,300]:
    for v2 in [100,150,200,260]:
        cl=v1+v2; op=abs(v1-v2)
        N.num("A.9.6",
            f"Two aircraft fly directly towards each other at {v1} kt and {v2} kt. What is their closing speed?",
            float(cl), [float(op), float(v1), (v1+v2)*0.75], i0,
            f"Closing speed (head-on) = sum of groundspeeds = {v1} + {v2} = {cl} kt.","easy")

# A.9.2  Variation: True track -> Magnetic heading  (East least, West best)
for tt in range(0,360,30):
    for var in [3,5,8,10,12,15,18,20]:
        for ew in ['E','W']:
            mh=(tt-var)%360 if ew=='E' else (tt+var)%360
            N.text("A.9.2",
                f"True track is {tt:03d}° and the magnetic variation is {var}°{ew}. What is the magnetic track?",
                f"{mh:03d}°",
                [f"{((tt+var)%360) if ew=='E' else ((tt-var)%360):03d}°", f"{(tt+2*var)%360:03d}°", f"{tt:03d}°"],
                f"Variation {ew}: magnetic = true {'−' if ew=='E' else '+'} variation ('East least, West best') = {tt} {'−' if ew=='E' else '+'} {var} = {mh:03d}°.","easy")

# A.9.7  Fuel required = flow x time
for flow in [400,600,900,1200,1800]:
    for mins in [30,45,90,120,210]:
        fuel=flow*mins/60.0
        N.num("A.9.7",
            f"Fuel flow is {flow} kg/h. How much fuel is burned in {mins} minutes?",
            fuel, [flow*mins, fuel*1.1, flow*mins/100.0], lambda v: f"{v:.0f} kg",
            f"Fuel = flow × time = {flow} kg/h × {mins}/60 h ≈ {fuel:.0f} kg.","easy")

N.dump("General Navigation", "NAV_AUTHORED_QUESTIONS",
       "src/app/data/nav-questions-authored.ts")
sys.stderr.write(f"NAV authored: {N.n}\n")

# ───────────────────────── RADIO NAVIGATION ─────────────────────────
R=Bank("RNAU")

# A.10.1  VHF line-of-sight range  d(NM)=1.23*(sqrt(h1)+sqrt(h2)), h in ft
for h1 in [500,1000,2000,5000,10000,20000,30000]:
    for h2 in [0,50,100,1000,5000]:
        d=1.23*(math.sqrt(h1)+math.sqrt(h2))
        R.num("A.10.1",
            f"An aircraft at {h1} ft works a VHF station at {h2} ft. What is the approximate theoretical line-of-sight range?",
            d, [1.23*math.sqrt(h1+h2), d*1.2, 1.23*(math.sqrt(h1)-math.sqrt(h2)) if h2 else d*0.8], lambda v: f"{v:.0f} NM",
            f"LOS range = 1.23(√h1 + √h2) = 1.23(√{h1} + √{h2}) ≈ {d:.0f} NM.","medium")

# A.10.1  Wavelength lambda = 300 / f(MHz)  metres  (also other bands)
freqs=[("kHz",200,300000),("kHz",400,300000),("MHz",2,300),("MHz",5,300),("MHz",75,300),("MHz",118,300),("MHz",330,300),("GHz",1.0,0.3),("GHz",3,0.3),("GHz",9,0.3)]
for unit,f,k in freqs:
    lam=k/f
    R.num("A.10.1",
        f"What is the wavelength of a {f} {unit} radio signal?",
        lam, [k/f*0.5, k/f*2, k/f*1.1], lambda v: (f"{v:.2f} m" if v<10 else f"{v:.0f} m"),
        f"λ = c/f = {('300 000 km/s' )}; λ(m) = {k}/f({unit}) = {k}/{f} ≈ {lam:.2f} m.","medium")

# A.10.1  Frequency band classification
bands=[(0.2,"LF (30-300 kHz)"),(0.8,"MF (300-3000 kHz)"),(2,"MF (300-3000 kHz)"),(10,"HF (3-30 MHz)"),(75,"VHF (30-300 MHz)"),(120,"VHF (30-300 MHz)"),(400,"UHF (300-3000 MHz)"),(1090,"UHF (300-3000 MHz)"),(5000,"SHF (3-30 GHz)"),(9000,"SHF (3-30 GHz)")]
allbands=["LF (30-300 kHz)","MF (300-3000 kHz)","HF (3-30 MHz)","VHF (30-300 MHz)","UHF (300-3000 MHz)","SHF (3-30 GHz)"]
for fMHz,corr in bands:
    disp=f"{fMHz*1000:.0f} kHz" if fMHz<1 else (f"{fMHz:.0f} MHz" if fMHz<1000 else f"{fMHz/1000:.1f} GHz")
    wrong=[b for b in allbands if b!=corr][:3]
    R.text("A.10.1",
        f"In which frequency band does {disp} lie?",
        corr, wrong,
        f"{disp} falls within {corr}.","easy")

# A.10.4  DME slant range vs ground range  (alt ft -> NM /6076)
for gnd in [20,40,60,80,100]:
    for ft in [6076,12152,18228,30380,36456]:
        altnm=ft/6076.0; slant=math.sqrt(gnd**2+altnm**2)
        R.num("A.10.4",
            f"An aircraft {ft} ft above a DME beacon reads {gnd} NM ground range equivalent. What DME (slant) range does it indicate? (1 NM ≈ 6076 ft)",
            slant, [float(gnd), gnd+altnm, slant*1.1], i1,
            f"Slant = √(ground² + height²); height = {ft}/6076 = {altnm:.1f} NM; √({gnd}²+{altnm:.1f}²) ≈ {slant:.1f} NM.","hard")
# DME slant error directly overhead
for ft in [6076,12152,24304,36456]:
    altnm=ft/6076.0
    R.num("A.10.4",
        f"An aircraft is directly overhead a DME beacon at {ft} ft. What slant range will the DME indicate?",
        altnm, [0.0, altnm*2, altnm+1], i1,
        f"Overhead, slant range = height only = {ft}/6076 ≈ {altnm:.1f} NM (ground range zero).","medium")

# A.10.5  Radar max unambiguous range  Rmax(NM)=c/(2*PRF)/1852
for prf in [200,300,400,500,750,1000,1200]:
    rmax=3e8/(2*prf)/1852.0
    R.num("A.10.5",
        f"A primary radar has a pulse recurrence frequency (PRF) of {prf} pps. What is its maximum unambiguous range?",
        rmax, [3e8/prf/1852.0, rmax*0.5, rmax*1.2], lambda v: f"{v:.0f} NM",
        f"Rmax = c/(2×PRF) = 3×10⁸/(2×{prf}) = {3e8/(2*prf):.0f} m ÷ 1852 ≈ {rmax:.0f} NM.","hard")

# A.10.5  Radar minimum range / resolution from pulse width  = c*tau/2
for tau in [0.5,1,2,3,5,0.25]:
    mr=3e8*(tau*1e-6)/2
    R.num("A.10.5",
        f"A radar transmits a pulse of {tau} microseconds. What is the minimum detection range (= c×τ/2)?",
        mr, [3e8*tau*1e-6, mr*2, mr*0.5], lambda v: f"{v:.0f} m",
        f"Min range = c×τ/2 = 3×10⁸ × {tau}×10⁻⁶ / 2 ≈ {mr:.0f} m.","hard")

# A.10.2  ADF: QDM = (RB + Heading) mod 360 ; QDR = QDM +/- 180
for hdg in [0,45,90,135,180,225,270,315,30,200,320]:
    for rb in [20,45,90,160,250,300,340]:
        qdm=(rb+hdg)%360; qdr=(qdm+180)%360
        R.num("A.10.2",
            f"Aircraft heading {hdg:03d}°(M); the ADF relative bearing of the NDB is {rb:03d}°. What is the QDM (magnetic bearing TO the beacon)?",
            qdm, [qdr, (hdg-rb)%360, (rb-hdg)%360], lambda v: f"{int(round(v))%360:03d}°",
            f"QDM = (relative bearing + heading) mod 360 = ({rb}+{hdg}) mod 360 = {qdm:03d}°.","medium")
for hdg in [10,80,160,240,300]:
    for rb in [30,110,200,290]:
        qdm=(rb+hdg)%360; qdr=(qdm+180)%360
        R.num("A.10.2",
            f"Aircraft heading {hdg:03d}°(M); ADF relative bearing {rb:03d}°. What is the QDR (magnetic bearing FROM the beacon)?",
            qdr, [qdm, (hdg-rb)%360, (qdr+180)%360], lambda v: f"{int(round(v))%360:03d}°",
            f"QDM = ({rb}+{hdg}) mod 360 = {qdm:03d}°; QDR = QDM ± 180 = {qdr:03d}°.","medium")

# A.10.3  VOR: aircraft on radial R -> QDM to station = (R+180) mod 360
for rad in [0,30,60,90,135,180,225,270,315,45,120,200,300]:
    qdm=(rad+180)%360
    R.num("A.10.3",
        f"An aircraft is on the {rad:03d}° radial from a VOR. What is the QDM (magnetic track to the station)?",
        qdm, [float(rad), (rad+90)%360, (rad-180)%360], lambda v: f"{int(round(v))%360:03d}°",
        f"The radial is the QDR (bearing FROM). QDM = radial ± 180 = ({rad}+180) mod 360 = {qdm:03d}°.","medium")

# A.10.12  GPS satellites / RAIM
gps=[("a 2D (latitude/longitude) position fix","3 satellites",["2 satellites","4 satellites","1 satellite"]),
     ("a 3D (including altitude) position fix","4 satellites",["3 satellites","5 satellites","2 satellites"]),
     ("RAIM (fault detection)","5 satellites",["4 satellites","3 satellites","6 satellites"]),
     ("RAIM with fault detection and exclusion (FDE)","6 satellites",["5 satellites","4 satellites","7 satellites"])]
for need,corr,wrong in gps:
    R.text("A.10.12",
        f"What is the minimum number of satellites required for {need}?",
        corr, wrong,
        f"GPS needs {corr} for {need} (3=2D, 4=3D, 5=RAIM, 6=FDE).","medium")

# pad radio with more VHF LOS single-station (receiver at sea level approx 1.25*sqrt(h))
for h1 in [1500,3000,7000,15000,25000,35000,40000,45000]:
    d=1.23*math.sqrt(h1)
    R.num("A.10.1",
        f"Neglecting the ground-station height, what is the approximate VHF line-of-sight range for an aircraft at {h1} ft?",
        d, [1.23*h1/1000.0, d*1.25, d*0.8], lambda v: f"{v:.0f} NM",
        f"Range ≈ 1.23√h = 1.23√{h1} ≈ {d:.0f} NM.","easy")

# A.10.1  Frequency from wavelength  f(MHz)=300/lambda(m)
for lam in [0.1,0.3,0.5,1,2,3.3,5,10,100,1500]:
    f=300.0/lam
    disp=(f"{f:.0f} MHz" if f<1000 else f"{f/1000:.2f} GHz")
    R.num("A.10.1",
        f"A radio wave has a wavelength of {lam} m. What is its frequency?",
        f, [300.0/lam*0.5, 300.0/lam*2, 150.0/lam], lambda v,disp=disp: (f"{v:.0f} MHz" if v<1000 else f"{v/1000:.2f} GHz"),
        f"f = c/λ; f(MHz) = 300/λ(m) = 300/{lam} ≈ {f:.0f} MHz.","medium")

# A.10.2/3  QTE (true bearing from station) = QDR +/- variation
for qdr in range(0,360,15):
    for var in [4,7,11,15]:
        for ew in ['E','W']:
            qte=(qdr+var)%360 if ew=='E' else (qdr-var)%360
            R.text("A.10.2",
                f"An NDB bears QDR {qdr:03d}° (magnetic, FROM the station). Magnetic variation is {var}°{ew}. What is the QTE (true bearing from the station)?",
                f"{qte:03d}°",
                [f"{((qdr-var)%360) if ew=='E' else ((qdr+var)%360):03d}°", f"{(qdr+180)%360:03d}°", f"{qdr:03d}°"],
                f"QTE = QDR {'+' if ew=='E' else '−'} variation (East add, West subtract to true) = {qdr} {'+' if ew=='E' else '−'} {var} = {qte:03d}°.","medium")

# A.10.3/10  Fixed facility frequency-band facts
